namespace sv_8d0756cd0f3145fcb2b1987fc2954bc2.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

@page "/apply"
@rendermode InteractiveServer
@using sv_8d0756cd0f3145fcb2b1987fc2954bc2.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h1>Job Application</h1>

    @* Step Indicator Bar *@
    <div class="step-indicator">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var stepIndex = i;
            var stepClass = GetStepClass(stepIndex);
            <div class="step @stepClass" @onclick="() => NavigateToStep(stepIndex)">
                <div class="step-circle">
                    @if (IsStepCompleted(stepIndex))
                    {
                        <span class="checkmark">✓</span>
                    }
                    else
                    {
                        <span>@(stepIndex + 1)</span>
                    }
                </div>
                <div class="step-label">@StepNames[stepIndex]</div>
            </div>
            @if (stepIndex < StepNames.Length - 1)
            {
                <div class="step-connector @(IsStepCompleted(stepIndex) ? "completed" : "")"></div>
            }
        }
    </div>

    @* Validation Errors *@
    @if (validationErrors.Count > 0)
    {
        <div class="validation-errors">
            <ul>
                @foreach (var error in validationErrors)
                {
                    <li>@error</li>
                }
            </ul>
        </div>
    }

    @* Step Content *@
    <div class="step-content">
        @switch (currentStep)
        {
            case 0:
                @RenderPersonalInfo()
                break;
            case 1:
                @RenderWorkHistory()
                break;
            case 2:
                @RenderReferences()
                break;
            case 3:
                @RenderCoverLetter()
                break;
            case 4:
                @RenderReviewSubmit()
                break;
        }
    </div>
</div>

@* Step 1: Personal Info *@
@{
    RenderFragment RenderPersonalInfo() => __builder =>
    {
        <h2>Personal Information</h2>
        <div class="form-group">
            <label for="fullName">Full Name *</label>
            <input id="fullName" type="text" @bind="personalFullName" @bind:event="oninput" placeholder="Enter your full name" />
        </div>
        <div class="form-group">
            <label for="email">Email *</label>
            <input id="email" type="email" @bind="personalEmail" @bind:event="oninput" placeholder="Enter your email" />
        </div>
        <div class="form-group">
            <label for="phone">Phone *</label>
            <input id="phone" type="tel" @bind="personalPhone" @bind:event="oninput" placeholder="Enter your phone number" />
        </div>
        <div class="form-group">
            <label for="address">Address *</label>
            <textarea id="address" @bind="personalAddress" @bind:event="oninput" placeholder="Enter your address"></textarea>
        </div>
        <div class="form-buttons">
            <button class="btn-next" @onclick="NextStep" disabled="@isProcessing">
                @if (isProcessing)
                {
                    <span>Validating...</span>
                }
                else
                {
                    <span>Next</span>
                }
            </button>
        </div>
    };
}

@* Step 2: Work History *@
@{
    RenderFragment RenderWorkHistory() => __builder =>
    {
        <h2>Work History</h2>
        @for (int i = 0; i < workEntries.Count; i++)
        {
            var index = i;
            <div class="work-entry-card">
                <div class="work-entry-header">
                    <h3>Position @(index + 1)</h3>
                    @if (workEntries.Count > 1)
                    {
                        <button class="btn-remove" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Company Name *</label>
                    <input type="text" @bind="workEntries[index].Company" @bind:event="oninput" placeholder="Company name" />
                </div>
                <div class="form-group">
                    <label>Job Title *</label>
                    <input type="text" @bind="workEntries[index].Title" @bind:event="oninput" placeholder="Job title" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Start Date *</label>
                        <input type="date" @bind="workEntries[index].StartDate" />
                    </div>
                    <div class="form-group">
                        <label>End Date</label>
                        <input type="date" @bind="workEntries[index].EndDate" disabled="@workEntries[index].IsCurrent" />
                    </div>
                    <div class="form-group checkbox-group">
                        <label>
                            <input type="checkbox" @bind="workEntries[index].IsCurrent" />
                            Currently working here
                        </label>
                    </div>
                </div>
                <div class="form-group">
                    <label>Description</label>
                    <textarea @bind="workEntries[index].Description" @bind:event="oninput" placeholder="Describe your responsibilities and achievements"></textarea>
                </div>
            </div>
        }
        <button class="btn-add" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    };
}

@* Step 3: References *@
@{
    RenderFragment RenderReferences() => __builder =>
    {
        <h2>References</h2>
        @for (int i = 0; i < references.Count; i++)
        {
            var index = i;
            <div class="reference-card">
                <div class="work-entry-header">
                    <h3>Reference @(index + 1)</h3>
                    @if (references.Count > 2)
                    {
                        <button class="btn-remove" @onclick="() => RemoveReference(index)">Remove</button>
                    }
                </div>
                <div class="form-group">
                    <label>Name *</label>
                    <input type="text" @bind="references[index].Name" @bind:event="oninput" placeholder="Reference name" />
                </div>
                <div class="form-group">
                    <label>Relationship *</label>
                    <input type="text" @bind="references[index].Relationship" @bind:event="oninput" placeholder="e.g., Former Manager" />
                </div>
                <div class="form-row">
                    <div class="form-group">
                        <label>Email *</label>
                        <input type="email" @bind="references[index].Email" @bind:event="oninput" placeholder="Email address" />
                    </div>
                    <div class="form-group">
                        <label>Phone *</label>
                        <input type="tel" @bind="references[index].Phone" @bind:event="oninput" placeholder="Phone number" />
                    </div>
                </div>
            </div>
        }
        @if (references.Count < 3)
        {
            <button class="btn-add" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    };
}

@* Step 4: Cover Letter *@
@{
    RenderFragment RenderCoverLetter() => __builder =>
    {
        <h2>Cover Letter</h2>
        <div class="form-group">
            <label for="coverLetter">Write your cover letter</label>
            <textarea id="coverLetter" class="cover-letter-input" @bind="coverLetter" @bind:event="oninput"
                      placeholder="Tell us why you're a great fit for this position..." maxlength="2000"></textarea>
            <div class="character-count @(coverLetter.Length > 1800 ? "warning" : "")">
                @coverLetter.Length / 2000 characters
            </div>
        </div>
        <div class="form-buttons">
            <button class="btn-back" @onclick="PreviousStep">Back</button>
            <button class="btn-next" @onclick="NextStep">Next</button>
        </div>
    };
}

@* Step 5: Review & Submit *@
@{
    RenderFragment RenderReviewSubmit() => __builder =>
    {
        @if (isSubmitted)
        {
            <div class="submission-confirmation">
                <div class="success-icon">✓</div>
                <h2>Application Submitted Successfully!</h2>
                <p>Your application ID is: <strong>@submittedApplicationId</strong></p>
                <p>We'll be in touch soon. Thank you for applying!</p>
            </div>
        }
        else
        {
            <h2>Review & Submit</h2>

            <div class="review-section">
                <div class="review-header">
                    <h3>Personal Information</h3>
                    <button class="btn-edit" @onclick="() => NavigateToStep(0)">Edit</button>
                </div>
                <div class="review-content">
                    <p><strong>Name:</strong> @personalFullName</p>
                    <p><strong>Email:</strong> @personalEmail</p>
                    <p><strong>Phone:</strong> @personalPhone</p>
                    <p><strong>Address:</strong> @personalAddress</p>
                </div>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Work History</h3>
                    <button class="btn-edit" @onclick="() => NavigateToStep(1)">Edit</button>
                </div>
                <div class="review-content">
                    @foreach (var entry in workEntries)
                    {
                        <div class="review-work-entry">
                            <p><strong>@entry.Title</strong> at @entry.Company</p>
                            <p>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</p>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="review-description">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>References</h3>
                    <button class="btn-edit" @onclick="() => NavigateToStep(2)">Edit</button>
                </div>
                <div class="review-content">
                    @foreach (var reference in references)
                    {
                        <div class="review-reference">
                            <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                            <p>@reference.Email | @reference.Phone</p>
                        </div>
                    }
                </div>
            </div>

            <div class="review-section">
                <div class="review-header">
                    <h3>Cover Letter</h3>
                    <button class="btn-edit" @onclick="() => NavigateToStep(3)">Edit</button>
                </div>
                <div class="review-content">
                    <p class="review-cover-letter">@coverLetter</p>
                </div>
            </div>

            <div class="form-buttons">
                <button class="btn-back" @onclick="PreviousStep">Back</button>
                <button class="btn-submit" @onclick="SubmitApplication" disabled="@isProcessing">
                    @if (isProcessing)
                    {
                        <span>Submitting...</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        }
    };
}

