namespace sv_8d0756cd0f3145fcb2b1987fc2954bc2.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    transition: all 0.3s ease;
}

.step.active .step-circle {
    background-color: #4361ee;
    color: white;
    box-shadow: 0 0 0 4px rgba(67, 97, 238, 0.2);
}

.step.completed .step-circle {
    background-color: #2ec4b6;
    color: white;
}

.step.future .step-circle {
    background-color: #e0e0e0;
    color: #999;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    color: #666;
    max-width: 80px;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step.future .step-label {
    color: #999;
}

.step-connector {
    flex: 1;
    height: 2px;
    background-color: #e0e0e0;
    margin: 0 0.25rem;
    margin-bottom: 1.5rem;
    max-width: 60px;
}

.step-connector.completed {
    background-color: #2ec4b6;
}

.checkmark {
    font-size: 1rem;
}

/* Form Elements */
.step-content {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
    border-bottom: 2px solid #f0f0f0;
    padding-bottom: 0.75rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.7rem 1rem;
    border: 1px solid #ddd;
    border-radius: 8px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    border-color: #4361ee;
    outline: none;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-row {
    display: flex;
    gap: 1rem;
    flex-wrap: wrap;
}

.form-row .form-group {
    flex: 1;
    min-width: 150px;
}

.checkbox-group {
    display: flex;
    align-items: center;
    padding-top: 1.5rem;
}

.checkbox-group label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
    font-weight: normal;
}

/* Buttons */
.form-buttons {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #f0f0f0;
}

.btn-next, .btn-submit {
    background-color: #4361ee;
    color: white;
    border: none;
    padding: 0.75rem 2rem;
    border-radius: 8px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
    transition: background-color 0.2s;
    margin-left: auto;
}

.btn-next:hover, .btn-submit:hover {
    background-color: #3651d4;
}

.btn-next:disabled, .btn-submit:disabled {
    background-color: #a0a0a0;
    cursor: not-allowed;
}

.btn-back {
    background-color: transparent;
    color: #666;
    border: 1px solid #ddd;
    padding: 0.75rem 2rem;
    border-radius: 8px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-back:hover {
    border-color: #4361ee;
    color: #4361ee;
}

.btn-add {
    background-color: transparent;
    color: #4361ee;
    border: 1px dashed #4361ee;
    padding: 0.6rem 1.5rem;
    border-radius: 8px;
    font-size: 0.9rem;
    cursor: pointer;
    width: 100%;
    margin-top: 1rem;
    transition: all 0.2s;
}

.btn-add:hover {
    background-color: rgba(67, 97, 238, 0.05);
}

.btn-remove {
    background-color: transparent;
    color: #e63946;
    border: 1px solid #e63946;
    padding: 0.3rem 0.8rem;
    border-radius: 6px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-remove:hover {
    background-color: #e63946;
    color: white;
}

.btn-edit {
    background: none;
    border: none;
    color: #4361ee;
    cursor: pointer;
    font-size: 0.9rem;
    text-decoration: underline;
    padding: 0;
}

.btn-edit:hover {
    color: #3651d4;
}

/* Work Entry & Reference Cards */
.work-entry-card, .reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 10px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background-color: #fafafa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    color: #333;
    font-size: 1rem;
}

/* Cover Letter */
.cover-letter-input {
    min-height: 250px !important;
    font-family: inherit;
    line-height: 1.6;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.5rem;
}

.character-count.warning {
    color: #e63946;
    font-weight: 500;
}

/* Validation Errors */
.validation-errors {
    background-color: #fff0f0;
    border: 1px solid #ffcdd2;
    border-radius: 8px;
    padding: 1rem 1.5rem;
    margin-bottom: 1.5rem;
}

.validation-errors ul {
    margin: 0;
    padding-left: 1.2rem;
}

.validation-errors li {
    color: #c62828;
    font-size: 0.9rem;
    margin-bottom: 0.3rem;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 10px;
    padding: 1.25rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

.review-content p {
    margin: 0.3rem 0;
    font-size: 0.9rem;
    color: #555;
}

.review-work-entry, .review-reference {
    padding: 0.5rem 0;
    border-bottom: 1px solid #f0f0f0;
}

.review-work-entry:last-child, .review-reference:last-child {
    border-bottom: none;
}

.review-description {
    font-style: italic;
    color: #777 !important;
}

.review-cover-letter {
    white-space: pre-wrap;
    background-color: #f9f9f9;
    padding: 1rem;
    border-radius: 6px;
    line-height: 1.6;
}

/* Submission Confirmation */
.submission-confirmation {
    text-align: center;
    padding: 3rem 1rem;
}

.success-icon {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    background-color: #2ec4b6;
    color: white;
    font-size: 2rem;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1.5rem;
}

.submission-confirmation h2 {
    border: none;
    color: #2ec4b6;
}

.submission-confirmation p {
    color: #555;
    font-size: 1.1rem;
}

.btn-submit {
    background-color: #2ec4b6;
}

.btn-submit:hover {
    background-color: #25a99d;
}

